mapper.select:
select patrol_id,patrol_name,device_code,channel_code,tenant_id,creator,create_time,case if_cruise when 1 then 0 else 1 end  as isCruise,
start_stop,start_time_period,start_stop_date,order_code
from vm_patrol_info_t where 1 = 1

    AND channel_code= #{channelCode}


    AND device_code= #{deviceCode}


    AND industry_code= #{industryCode}


    AND tenant_id= #{customerCode}


    AND patrol_id= #{patrolId}


    AND delete_flag= #{deleteFlag}

    select count(*)
	from vm_order_devices
	where delete_flag = '0'
	and device_code = #{deviceCode}
	and tenant_id = #{tenantId}
	and ord_status in (0,1,2)

    select order_code,device_code
	from vm_order_devices
	where delete_flag = '0'
	and device_code = #{deviceCode}
	and tenant_id = #{tenantId}
	and industry_code = #{industryCode}
	and ord_status in (0,1,2)

